def clamp_unit(x: float) -> float | None:
    if x < 0 or x > 100 or not isinstance(x, (float, int)):
        return None
    if x > 1:
        if x <= 10:
            x /= 10
        elif x <= 100:
            x /= 100
        else:
            return None
    return max(0, min(1, x))

import pytest

def test_clamp_unit():
    assert clamp_unit(5) == 0.5
    assert clamp_unit(50) == 0.5
    assert clamp_unit(500) == None
    assert clamp_unit(1.5) == 0.15
    assert clamp_unit(15) == 0.15
    assert clamp_unit(150) == None
    assert clamp_unit(-5) == None
    assert clamp_unit(float('nan')) == None
